use super::{ActivateOptions, Shell};
use std::fmt;

pub struct Zsh;

impl Shell for Zsh {
    fn activate(&self, opts: ActivateOptions) -> String {
        let mut out = String::new();
        let exe = opts.exe.display().to_string();

        // Export shell type
        out.push_str("export FNOX_SHELL=zsh\n");

        // A nested zsh inherits its parent's environment. Discard the encoded
        // parent session so the child's first hook creates independently owned
        // as_file paths instead of deleting the parent's paths on exit.
        out.push_str(
            r#"if [[ -n "${__FNOX_SESSION:-}" && "${__FNOX_ZSH_PID:-}" != "$$" ]]; then
  unset __FNOX_SESSION
fi
export __FNOX_ZSH_PID=$$
"#,
        );

        // Define the fnox wrapper function
        out.push_str(&format!(
            r#"
fnox() {{
  local command output status
  command="${{1:-}}"
  if [ "$#" = 0 ]; then
    {exe}
    return
  fi
  shift

  case "$command" in
  deactivate|shell)
    output="$({exe} "$command" "$@")"
    status=$?
    if (( status != 0 )); then
      return $status
    fi
    eval "$output"
    ;;
  *)
    {exe} "$command" "$@"
    ;;
  esac
}}
"#,
        ));

        if !opts.no_hook_env {
            // Define the hook function
            out.push_str(&format!(
                r#"
_fnox_hook() {{
  trap -- '' SIGINT
  eval "$({exe} hook-env -s zsh)"
  trap - SIGINT
}}

_fnox_cleanup() {{
  {exe} deactivate >/dev/null
}}
"#,
            ));

            // Add hook to precmd_functions
            out.push_str(
                r#"
typeset -ag precmd_functions
if [[ -z "${precmd_functions[(r)_fnox_hook]+1}" ]]; then
  precmd_functions=( _fnox_hook ${precmd_functions[@]} )
    hasher.update(value.as_bytes());
    hasher.finalize().to_hex().to_string()
}

/// Public API for computing hashes with a given session's key
pub fn hash_secret_value_with_session(session: &HookEnvSession, key: &str, value: &str) -> String {
    hash_secret_with_key(&session.hash_key, key, value)
}

/// Check if we should exit early (optimization)
/// Returns true if nothing changed and we can skip work
pub fn should_exit_early() -> bool {
    // Check if fnox.toml was modified
    if has_config_been_modified() {
        tracing::debug!("fnox.toml modified, must run hook-env");
        return false;
    }

    // Check if FNOX_* env vars changed
    if has_fnox_env_vars_changed() {
        tracing::debug!("FNOX_* env vars changed, must run hook-env");
        return false;
    }

    tracing::debug!("no changes detected, exiting early");
    true
}

/// Check if any config files in the hierarchy have been modified since last run
/// This checks all fnox.toml and fnox.local.toml files from current directory up to root
fn has_config_been_modified() -> bool {
    let current_dir = match std::env::current_dir() {
        Ok(dir) => dir,
        Err(_) => return true, // If we can't get current dir, force reload
    };

