#!/usr/bin/env bats

setup() {
	load 'test_helper/common_setup'
	_common_setup
	export XDG_RUNTIME_DIR="$TEST_TEMP_DIR/runtime"
	mkdir -p "$XDG_RUNTIME_DIR"
}

teardown() {
	"$FNOX_BIN" daemon stop >/dev/null 2>&1 || true
	"$FNOX_BIN" --profile dev daemon stop >/dev/null 2>&1 || true
	"$FNOX_BIN" --profile staging daemon stop >/dev/null 2>&1 || true
	"$FNOX_BIN" --profile staging --no-defaults daemon stop >/dev/null 2>&1 || true
	_common_teardown
}

daemon_config() {
	cat >fnox.toml <<'EOF'
root = true

[daemon]
enabled = true

[providers.plain]
type = "plain"

[secrets]
FOO = { provider = "plain", value = "bar" }
FILE_SECRET = { provider = "plain", value = "file-value", as_file = true }
HIDDEN = { provider = "plain", value = "hidden-value", env = false }
EOF
}

